/**
 * dev_scripts/legacy-assimilation-atlas.mjs
 *
 * Classifies a legacy subtree for assimilation into Frame Conn.
 * This tool is static-only: it never imports or executes target code.
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import os from "node:os";
import { fileURLToPath } from "node:url";

const SCRIPT_VERSION = "1.0.0";
const SCRIPT_FILE = fileURLToPath(import.meta.url);
const SCRIPT_DIRECTORY = path.dirname(SCRIPT_FILE);
const REPOSITORY_ROOT = path.resolve(SCRIPT_DIRECTORY, "..");
const SOURCE_EXTENSIONS = new Set([".js", ".mjs", ".cjs", ".css", ".json", ".md"]);
const IGNORED_DIRECTORIES = new Set([".git", "node_modules", "dist", "build", "coverage", "backups", "patch-history"]);

const DISPOSITIONS = Object.freeze({
  PRESERVE: "PRESERVE",
  REUSE_EXISTING: "REUSE_EXISTING",
  MOVE_DOMAIN: "MOVE_DOMAIN",
  REWRITE_ADAPTER: "REWRITE_ADAPTER",
  REPLACE_UI: "REPLACE_UI",
  DELETE_SHELL: "DELETE_SHELL",
  COMPATIBILITY: "COMPATIBILITY",
  UNKNOWN: "UNKNOWN"
});

function normalizeSlashes(value) {
  return String(value).replaceAll("\\", "/");
}

function parseArgs(argv) {
  const args = {
    legacyRoot: "scripts/dm_features/sitreps/legacy-sitrep-module",
    targetRoot: "scripts/dm_features/sitreps",
    output: "legacy-assimilation-report.json",
    parityOutput: "legacy-parity.json",
    selfTest: false
  };

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === "--legacy-root") args.legacyRoot = argv[++index];
    else if (token === "--target-root") args.targetRoot = argv[++index];
    else if (token === "--output") args.output = argv[++index];
    else if (token === "--parity-output") args.parityOutput = argv[++index];
    else if (token === "--no-parity") args.parityOutput = null;
    else if (token === "--self-test") args.selfTest = true;
    else if (token === "--help" || token === "-h") {
      console.log("Usage: node dev_scripts/legacy-assimilation-atlas.mjs [--legacy-root path] [--target-root path] [--output file] [--parity-output file|--no-parity] [--self-test]");
      process.exit(0);
    }
  }

  return args;
}

function collectFiles(root) {
  if (!fs.existsSync(root)) return [];
  const result = [];

  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isDirectory() && IGNORED_DIRECTORIES.has(entry.name)) continue;
    const absolute = path.join(root, entry.name);
    if (entry.isDirectory()) result.push(...collectFiles(absolute));
    else if (entry.isFile() && SOURCE_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) result.push(absolute);
  }

  return result.sort();
}

function lineNumber(text, index) {
  return text.slice(0, index).split("\n").length;
}

function addFinding(findings, file, text, matchIndex, kind, disposition, reason, target = null, evidence = null) {
  findings.push({
    kind,
    disposition,
    file,
    line: lineNumber(text, matchIndex),
    reason,
    target,
    evidence
  });
}

function scanFile(relativeFile, text) {
  const findings = [];
  const isCss = relativeFile.endsWith(".css");
  const basename = path.basename(relativeFile).toLowerCase();

  const rules = [
    {
      kind: "runtime-hook",
      disposition: DISPOSITIONS.DELETE_SHELL,
      regex: /\bHooks\s*\.\s*(?:once|on)\s*\(\s*["'`](init|ready)["'`]/g,
      reason: "Legacy startup/lifecycle authority must be absorbed by Frame Conn runtime composition.",
      target: "scripts/runtime-orchestrator.js + registered feature lifecycle"
    },
    {
      kind: "hook-registration",
      disposition: DISPOSITIONS.REWRITE_ADAPTER,
      regex: /\bHooks\s*\.\s*on\s*\(\s*["'`]([^"'`]+)["'`]/g,
      reason: "Direct Foundry hook ownership should be expressed through the host feature/lifecycle boundary.",
      target: "registered feature lifecycle / foundry integration"
    },
    {
      kind: "global-api",
      disposition: DISPOSITIONS.COMPATIBILITY,
      regex: /\bgame\s*\.\s*([A-Za-z_$][\w$]*)\s*=/g,
      reason: "Legacy public globals require an explicit compatibility or public-API composition decision.",
      target: "runtime-orchestrator public API composition"
    },
    {
      kind: "prototype-patch",
      disposition: DISPOSITIONS.MOVE_DOMAIN,
      regex: /\.prototype\s*\.\s*([A-Za-z_$][\w$]*)\s*=/g,
      reason: "Prototype patching is Foundry-platform behavior and should not remain owned by a SITREP feature.",
      target: "scripts/foundry_features/"
    },
    {
      kind: "persistent-flag",
      disposition: DISPOSITIONS.COMPATIBILITY,
      regex: /\.(getFlag|setFlag|unsetFlag)\s*\(/g,
      reason: "Persisted Foundry flags require namespace/data-shape migration review before ownership changes.",
      target: "state namespace migration plan"
    },
    {
      kind: "settings",
      disposition: DISPOSITIONS.COMPATIBILITY,
      regex: /\bgame\s*\.\s*settings\s*\.\s*(register|get|set)\s*\(/g,
      reason: "Legacy settings are persisted API surface and require an explicit migration decision.",
      target: "state namespace migration plan"
    },
    {
      kind: "chat-output",
      disposition: DISPOSITIONS.REWRITE_ADAPTER,
      regex: /\bChatMessage\s*\.\s*create\s*\(/g,
      reason: "Chat semantics may survive, but direct Foundry output should pass through the host integration boundary.",
      target: "shared Foundry integration/output service"
    },
    {
      kind: "dialog-ui",
      disposition: DISPOSITIONS.REPLACE_UI,
      regex: /\bnew\s+Dialog\s*\(/g,
      reason: "Legacy interaction intent can survive, but presentation should move into the DM application architecture.",
      target: "DM UI / SITREP presentation components"
    },
    {
      kind: "dom-ui",
      disposition: DISPOSITIONS.REPLACE_UI,
      regex: /\bdocument\s*\.\s*(?:createElement|getElementById|querySelector)\s*\(/g,
      reason: "Standalone DOM/HUD composition should be replaced by the host DM UI surface.",
      target: "DM UI / SITREP presentation components"
    },
    {
      kind: "window-listener",
      disposition: DISPOSITIONS.DELETE_SHELL,
      regex: /\bwindow\s*\.\s*addEventListener\s*\(/g,
      reason: "Application-shell event wiring should be owned by the host lifecycle/runtime.",
      target: "registered feature lifecycle"
    },
    {
      kind: "spatial-adjacency",
      disposition: DISPOSITIONS.REUSE_EXISTING,
      regex: /\b(?:tokensAreAdjacent|tokenBoundsInGridSpaces|testAdjacency)\b/g,
      reason: "Frame Conn already has shared targeting/spatial ownership; legacy spatial rules should delegate there.",
      target: "scripts/player_features/feature_targeting_spatial/ or shared targeting-spatial service"
    },
    {
      kind: "region-spatial",
      disposition: DISPOSITIONS.REWRITE_ADAPTER,
      regex: /\b(?:testInsideRegion|regions\?\.has|scene\?\.regions)\b/g,
      reason: "Region queries are useful but should be isolated behind a shared Foundry/spatial boundary.",
      target: "targeting/spatial or Foundry integration service"
    },
    {
      kind: "sitrep-domain",
      disposition: DISPOSITIONS.PRESERVE,
      regex: /\b(?:evaluateSitrep|calculateState|gauntletControlWeight|recordReconScan|resolveExtractionObjective|resolveEscortObjective|holdout|recon|escort|extraction|gauntlet)\b/gi,
      reason: "This appears to encode SITREP-specific domain behavior that should survive decomposition.",
      target: "scripts/dm_features/sitreps/"
    }
  ];

  for (const rule of rules) {
    rule.regex.lastIndex = 0;
    let match;
    while ((match = rule.regex.exec(text))) {
      addFinding(findings, relativeFile, text, match.index, rule.kind, rule.disposition, rule.reason, rule.target, match[0].replace(/\s+/g, " ").trim());
      if (match[0].length === 0) rule.regex.lastIndex += 1;
    }
  }

  if (isCss || basename.includes("ui-boilerplate") || basename.includes("tracker.css")) {
    findings.push({
      kind: "presentation-file",
      disposition: DISPOSITIONS.REPLACE_UI,
      file: relativeFile,
      line: 1,
      reason: "Legacy standalone presentation should be re-expressed in the DM UI architecture.",
      target: "styles/ui_dm/ or future SITREP DM UI components",
      evidence: basename
    });
  }

  if (basename.endsWith(".bak")) {
    findings.push({
      kind: "backup-artifact",
      disposition: DISPOSITIONS.DELETE_SHELL,
      file: relativeFile,
      line: 1,
      reason: "Legacy backup artifacts should not participate in the integrated source tree.",
      target: null,
      evidence: basename
    });
  }

  return findings;
}

function summarizeFile(file, findings) {
  const priority = [
    DISPOSITIONS.DELETE_SHELL,
    DISPOSITIONS.MOVE_DOMAIN,
    DISPOSITIONS.REUSE_EXISTING,
    DISPOSITIONS.COMPATIBILITY,
    DISPOSITIONS.REPLACE_UI,
    DISPOSITIONS.REWRITE_ADAPTER,
    DISPOSITIONS.PRESERVE,
    DISPOSITIONS.UNKNOWN
  ];
  const counts = Object.fromEntries(Object.values(DISPOSITIONS).map(value => [value, 0]));
  for (const finding of findings) counts[finding.disposition] += 1;
  const primaryDisposition = priority.find(value => counts[value] > 0) ?? DISPOSITIONS.UNKNOWN;
  return { file, primaryDisposition, counts, findingCount: findings.length };
}

function buildParityLedger(report) {
  const behaviors = [];
  const seen = new Set();
  for (const finding of report.findings) {
    if (finding.disposition !== DISPOSITIONS.PRESERVE) continue;
    const key = `${finding.file}:${finding.kind}:${finding.evidence}`;
    if (seen.has(key)) continue;
    seen.add(key);
    behaviors.push({
      legacy_behavior: finding.evidence,
      legacy_source: `${finding.file}:${finding.line}`,
      new_owner: finding.target,
      status: "NOT_MIGRATED",
      verification: []
    });
  }
  return {
    schema_version: 1,
    generated_by: `legacy-assimilation-atlas ${SCRIPT_VERSION}`,
    legacy_root: report.legacyRoot,
    target_root: report.targetRoot,
    statuses: ["NOT_MIGRATED", "PARTIALLY_MIGRATED", "MIGRATED_UNVERIFIED", "VERIFIED", "INTENTIONALLY_DROPPED"],
    behaviors
  };
}

function runAnalysis(repositoryRoot, legacyRootRelative, targetRootRelative) {
  const legacyRoot = path.resolve(repositoryRoot, legacyRootRelative);
  const files = collectFiles(legacyRoot);
  if (files.length === 0) throw new Error(`No analyzable files found under ${legacyRootRelative}`);

  const findings = [];
  const fileSummaries = [];
  for (const absolute of files) {
    const relative = normalizeSlashes(path.relative(repositoryRoot, absolute));
    const text = fs.readFileSync(absolute, "utf8");
    const fileFindings = scanFile(relative, text);
    findings.push(...fileFindings);
    fileSummaries.push(summarizeFile(relative, fileFindings));
  }

  const dispositionCounts = Object.fromEntries(Object.values(DISPOSITIONS).map(value => [value, 0]));
  for (const finding of findings) dispositionCounts[finding.disposition] += 1;

  return {
    schema_version: 1,
    tool: "legacy-assimilation-atlas",
    version: SCRIPT_VERSION,
    legacyRoot: normalizeSlashes(legacyRootRelative),
    targetRoot: normalizeSlashes(targetRootRelative),
    summary: {
      files: files.length,
      findings: findings.length,
      dispositionCounts,
      unknownFiles: fileSummaries.filter(item => item.primaryDisposition === DISPOSITIONS.UNKNOWN).length
    },
    files: fileSummaries,
    findings
  };
}

function printReport(report) {
  console.log("Frame Conn Legacy Assimilation Atlas");
  console.log(`Legacy root: ${report.legacyRoot}`);
  console.log(`Target root: ${report.targetRoot}`);
  console.log(`${report.summary.files} files | ${report.summary.findings} findings`);
  console.log("");
  console.log("Disposition counts:");
  for (const [name, count] of Object.entries(report.summary.dispositionCounts)) {
    if (count > 0) console.log(`  ${name}: ${count}`);
  }
  console.log("");
  console.log("File dispositions:");
  for (const file of report.files) console.log(`  ${file.primaryDisposition.padEnd(16)} ${file.file}`);
}

function selfTest() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "frame-conn-assimilation-"));
  const legacy = path.join(root, "legacy");
  fs.mkdirSync(legacy, { recursive: true });
  fs.writeFileSync(path.join(legacy, "program.js"), 'Hooks.once("ready", () => { game.oldApi = {}; });\n');
  fs.writeFileSync(path.join(legacy, "domain.js"), 'export function evaluateSitrep(){ return combat.getFlag("old", "sitrep"); }\n');
  const report = runAnalysis(root, "legacy", "target");
  const dispositions = new Set(report.findings.map(item => item.disposition));
  if (!dispositions.has(DISPOSITIONS.DELETE_SHELL) || !dispositions.has(DISPOSITIONS.COMPATIBILITY) || !dispositions.has(DISPOSITIONS.PRESERVE)) {
    throw new Error("Self-test failed: expected assimilation dispositions were not detected.");
  }
  fs.rmSync(root, { recursive: true, force: true });
  console.log("Legacy Assimilation Atlas self-test PASSED");
}

const args = parseArgs(process.argv);
if (args.selfTest) {
  selfTest();
} else {
  const report = runAnalysis(REPOSITORY_ROOT, args.legacyRoot, args.targetRoot);
  const outputPath = path.resolve(REPOSITORY_ROOT, args.output);
  fs.writeFileSync(outputPath, `${JSON.stringify(report, null, 2)}\n`);
  if (args.parityOutput) {
    const parityPath = path.resolve(REPOSITORY_ROOT, args.parityOutput);
    fs.writeFileSync(parityPath, `${JSON.stringify(buildParityLedger(report), null, 2)}\n`);
  }
  printReport(report);
  console.log(`\nReport: ${normalizeSlashes(path.relative(REPOSITORY_ROOT, outputPath))}`);
  if (args.parityOutput) console.log(`Parity ledger: ${normalizeSlashes(args.parityOutput)}`);
}

/**
 * dev_scripts/runtime-authority-audit.mjs
 *
 * Detects competing startup/runtime authorities, public globals, direct hook
 * ownership, window/document listeners, and platform monkey patches.
 * Static-only: target code is never imported or executed.
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import os from "node:os";
import { fileURLToPath } from "node:url";

const SCRIPT_VERSION = "1.0.0";
const SCRIPT_FILE = fileURLToPath(import.meta.url);
const SCRIPT_DIRECTORY = path.dirname(SCRIPT_FILE);
const REPOSITORY_ROOT = path.resolve(SCRIPT_DIRECTORY, "..");
const JS_EXTENSIONS = new Set([".js", ".mjs", ".cjs"]);
const IGNORED_DIRECTORIES = new Set([".git", ".github", "node_modules", "dist", "build", "coverage", "backups", "patch-history", "dev_scripts"]);

const AUTHORITY = Object.freeze({
  AUTHORITATIVE: "AUTHORITATIVE",
  REGISTERED_FEATURE_EFFECT: "REGISTERED_FEATURE_EFFECT",
  DIRECT_FEATURE_EFFECT: "DIRECT_FEATURE_EFFECT",
  COMPETING_RUNTIME_AUTHORITY: "COMPETING_RUNTIME_AUTHORITY",
  GLOBAL_PATCH: "GLOBAL_PATCH",
  PUBLIC_GLOBAL_API: "PUBLIC_GLOBAL_API"
});

function normalizeSlashes(value) {
  return String(value).replaceAll("\\", "/");
}

function parseArgs(argv) {
  const args = { root: ".", output: "runtime-authority-report.json", strict: false, selfTest: false };
  for (let i = 2; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === "--root") args.root = argv[++i];
    else if (token === "--output") args.output = argv[++i];
    else if (token === "--strict") args.strict = true;
    else if (token === "--self-test") args.selfTest = true;
    else if (token === "--help" || token === "-h") {
      console.log("Usage: node dev_scripts/runtime-authority-audit.mjs [--root path] [--output file] [--strict] [--self-test]");
      process.exit(0);
    }
  }
  return args;
}

function collectFiles(root) {
  if (!fs.existsSync(root)) return [];
  const result = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isDirectory() && IGNORED_DIRECTORIES.has(entry.name)) continue;
    const absolute = path.join(root, entry.name);
    if (entry.isDirectory()) result.push(...collectFiles(absolute));
    else if (entry.isFile() && JS_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) result.push(absolute);
  }
  return result.sort();
}

function lineNumber(text, index) {
  return text.slice(0, index).split("\n").length;
}

function authorityFor(relativeFile, kind, eventName = null) {
  const normalized = normalizeSlashes(relativeFile);
  const runtimeOwner = normalized === "scripts/runtime-orchestrator.js";
  const foundryIntegration = normalized === "scripts/foundry-integration-feature.js";
  const foundryFeature = normalized.startsWith("scripts/foundry_features/");
  const featureFamily = normalized.startsWith("scripts/player_features/") || normalized.startsWith("scripts/rules_features/") || normalized.startsWith("scripts/dm_features/");

  if (kind === "startup-hook") {
    if (runtimeOwner) return { authority: AUTHORITY.AUTHORITATIVE, severity: null, reason: "Authoritative application startup owner." };
    if (foundryIntegration) return { authority: AUTHORITY.REGISTERED_FEATURE_EFFECT, severity: "warning", reason: "Startup hook is outside the runtime orchestrator; verify it is intentionally delegated." };
    return { authority: AUTHORITY.COMPETING_RUNTIME_AUTHORITY, severity: "error", reason: `Direct ${eventName ?? "startup"} ownership competes with the authoritative runtime orchestrator.` };
  }

  if (kind === "hook") {
    if (runtimeOwner || foundryIntegration) return { authority: AUTHORITY.REGISTERED_FEATURE_EFFECT, severity: null, reason: "Hook occurs at an explicit runtime/Foundry integration boundary." };
    if (featureFamily || foundryFeature) return { authority: AUTHORITY.DIRECT_FEATURE_EFFECT, severity: "warning", reason: "Feature installs a Foundry hook directly; prefer registered lifecycle/runtime binding." };
    return { authority: AUTHORITY.DIRECT_FEATURE_EFFECT, severity: "warning", reason: "Direct Foundry hook has no recognized lifecycle owner." };
  }

  if (kind === "global-api") {
    if (runtimeOwner) return { authority: AUTHORITY.PUBLIC_GLOBAL_API, severity: null, reason: "Public game API is composed by the authoritative runtime." };
    return { authority: AUTHORITY.PUBLIC_GLOBAL_API, severity: "warning", reason: "Public game/global API is assigned outside authoritative runtime composition." };
  }

  if (kind === "prototype-patch") {
    if (foundryFeature) return { authority: AUTHORITY.GLOBAL_PATCH, severity: "warning", reason: "Platform patch is in the designated Foundry feature family; verify wrapper safety and reversibility." };
    return { authority: AUTHORITY.GLOBAL_PATCH, severity: "error", reason: "Prototype/platform patch exists outside scripts/foundry_features/." };
  }

  if (kind === "event-listener") {
    if (runtimeOwner || foundryIntegration || foundryFeature) return { authority: AUTHORITY.REGISTERED_FEATURE_EFFECT, severity: "warning", reason: "Browser listener exists at a plausible platform/runtime boundary; verify cleanup ownership." };
    return { authority: AUTHORITY.DIRECT_FEATURE_EFFECT, severity: "warning", reason: "Browser event listener is installed directly by feature code without explicit lifecycle ownership." };
  }

  if (kind === "application-construction") {
    return { authority: AUTHORITY.DIRECT_FEATURE_EFFECT, severity: null, reason: "Application/Dialog construction is informational; ownership depends on surrounding composition." };
  }

  return { authority: AUTHORITY.DIRECT_FEATURE_EFFECT, severity: null, reason: null };
}

const PATTERNS = [
  { kind: "startup-hook", regex: /\bHooks\s*\.\s*(?:once|on)\s*\(\s*["'`](init|ready|setup)["'`]/g, eventGroup: 1 },
  { kind: "hook", regex: /\bHooks\s*\.\s*on\s*\(\s*["'`]([^"'`]+)["'`]/g, eventGroup: 1 },
  { kind: "global-api", regex: /\b(?:game|globalThis)\s*\.\s*([A-Za-z_$][\w$]*)\s*=/g },
  { kind: "prototype-patch", regex: /\b([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\.prototype\.([A-Za-z_$][\w$]*)\s*=/g },
  { kind: "event-listener", regex: /\b(?:window|document)\s*\.\s*addEventListener\s*\(\s*["'`]([^"'`]+)["'`]/g, eventGroup: 1 },
  { kind: "application-construction", regex: /\bnew\s+(?:Application|ApplicationV2|Dialog|DialogV2)\s*\(/g }
];

function scanFile(relativeFile, text) {
  const findings = [];
  const seen = new Set();
  for (const pattern of PATTERNS) {
    pattern.regex.lastIndex = 0;
    let match;
    while ((match = pattern.regex.exec(text))) {
      // Startup hooks are also syntactically Hooks.on; avoid duplicate generic hook findings.
      if (pattern.kind === "hook" && ["init", "ready", "setup"].includes(match[1])) continue;
      const eventName = pattern.eventGroup ? match[pattern.eventGroup] : null;
      const key = `${pattern.kind}:${match.index}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const classification = authorityFor(relativeFile, pattern.kind, eventName);
      findings.push({
        kind: pattern.kind,
        authority: classification.authority,
        severity: classification.severity,
        reason: classification.reason,
        file: relativeFile,
        line: lineNumber(text, match.index),
        event: eventName,
        expression: match[0].replace(/\s+/g, " ").trim().slice(0, 180)
      });
      if (match[0].length === 0) pattern.regex.lastIndex += 1;
    }
  }
  return findings;
}

function runAudit(repositoryRoot, rootRelative) {
  const scanRoot = path.resolve(repositoryRoot, rootRelative);
  const files = collectFiles(scanRoot);
  const findings = [];
  for (const absolute of files) {
    const relative = normalizeSlashes(path.relative(repositoryRoot, absolute));
    findings.push(...scanFile(relative, fs.readFileSync(absolute, "utf8")));
  }
  const errors = findings.filter(item => item.severity === "error").length;
  const warnings = findings.filter(item => item.severity === "warning").length;
  const authorityCounts = {};
  for (const finding of findings) authorityCounts[finding.authority] = (authorityCounts[finding.authority] ?? 0) + 1;
  return {
    schema_version: 1,
    tool: "runtime-authority-audit",
    version: SCRIPT_VERSION,
    root: normalizeSlashes(rootRelative),
    summary: { files: files.length, findings: findings.length, errors, warnings, authorityCounts },
    findings
  };
}

function printReport(report) {
  console.log("Frame Conn Runtime Authority Audit");
  console.log(`Root: ${report.root}`);
  console.log(`${report.summary.files} files | ${report.summary.findings} authority sites | ${report.summary.errors} errors | ${report.summary.warnings} warnings`);
  const expanded = report.findings.filter(item => item.severity);
  if (expanded.length) {
    console.log("\nAuthority diagnostics:");
    for (const finding of expanded) {
      console.log(`  ${(finding.severity ?? "info").toUpperCase()} ${finding.authority} ${finding.file}:${finding.line}`);
      console.log(`    ${finding.reason}`);
      console.log(`    ${finding.expression}`);
    }
  }
}

function selfTest() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "frame-conn-runtime-authority-"));
  fs.mkdirSync(path.join(root, "scripts", "dm_features", "legacy"), { recursive: true });
  fs.mkdirSync(path.join(root, "scripts"), { recursive: true });
  fs.writeFileSync(path.join(root, "scripts", "runtime-orchestrator.js"), 'Hooks.once("ready", () => { game.frameConn = {}; });\n');
  fs.writeFileSync(path.join(root, "scripts", "dm_features", "legacy", "program.js"), 'Hooks.once("ready", () => { game.legacy = {}; });\n');
  const report = runAudit(root, ".");
  if (!report.findings.some(item => item.authority === AUTHORITY.AUTHORITATIVE) || !report.findings.some(item => item.authority === AUTHORITY.COMPETING_RUNTIME_AUTHORITY && item.severity === "error")) {
    throw new Error("Self-test failed: runtime authority distinction was not detected.");
  }
  fs.rmSync(root, { recursive: true, force: true });
  console.log("Runtime Authority Audit self-test PASSED");
}

const args = parseArgs(process.argv);
if (args.selfTest) {
  selfTest();
} else {
  const report = runAudit(REPOSITORY_ROOT, args.root);
  const outputPath = path.resolve(REPOSITORY_ROOT, args.output);
  fs.writeFileSync(outputPath, `${JSON.stringify(report, null, 2)}\n`);
  printReport(report);
  console.log(`\nReport: ${normalizeSlashes(path.relative(REPOSITORY_ROOT, outputPath))}`);
  if (args.strict && report.summary.errors > 0) process.exitCode = 1;
}

/**
 * dev_scripts/state-namespace-atlas.mjs
 *
 * Builds a persistence/public-namespace ledger over Frame Conn source.
 * Static-only: target code is never imported or executed.
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import os from "node:os";
import { fileURLToPath } from "node:url";

const SCRIPT_VERSION = "1.0.0";
const SCRIPT_FILE = fileURLToPath(import.meta.url);
const SCRIPT_DIRECTORY = path.dirname(SCRIPT_FILE);
const REPOSITORY_ROOT = path.resolve(SCRIPT_DIRECTORY, "..");
const JS_EXTENSIONS = new Set([".js", ".mjs", ".cjs"]);
const IGNORED_DIRECTORIES = new Set([".git", ".github", "node_modules", "dist", "build", "coverage", "backups", "patch-history", "dev_scripts"]);

function normalizeSlashes(value) {
  return String(value).replaceAll("\\", "/");
}

function parseArgs(argv) {
  const args = { root: ".", output: "state-namespace-report.json", selfTest: false };
  for (let i = 2; i < argv.length; i += 1) {
    const token = argv[i];
    if (token === "--root") args.root = argv[++i];
    else if (token === "--output") args.output = argv[++i];
    else if (token === "--self-test") args.selfTest = true;
    else if (token === "--help" || token === "-h") {
      console.log("Usage: node dev_scripts/state-namespace-atlas.mjs [--root path] [--output file] [--self-test]");
      process.exit(0);
    }
  }
  return args;
}

function collectFiles(root) {
  if (!fs.existsSync(root)) return [];
  const result = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isDirectory() && IGNORED_DIRECTORIES.has(entry.name)) continue;
    const absolute = path.join(root, entry.name);
    if (entry.isDirectory()) result.push(...collectFiles(absolute));
    else if (entry.isFile() && JS_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) result.push(absolute);
  }
  return result.sort();
}

function lineNumber(text, index) {
  return text.slice(0, index).split("\n").length;
}

function resolveLiteralOrIdentifier(token, constants) {
  const trimmed = String(token ?? "").trim();
  const literal = trimmed.match(/^["'`]([^"'`]*)["'`]$/);
  if (literal) return { value: literal[1], resolved: true, source: "literal" };
  if (/^[A-Za-z_$][\w$]*$/.test(trimmed) && constants.has(trimmed)) {
    return { value: constants.get(trimmed), resolved: true, source: `constant:${trimmed}` };
  }
  return { value: trimmed || "<unknown>", resolved: false, source: "expression" };
}

function collectStringConstants(text) {
  const constants = new Map();
  const regex = /\bconst\s+([A-Za-z_$][\w$]*)\s*=\s*["'`]([^"'`]*)["'`]\s*;/g;
  let match;
  while ((match = regex.exec(text))) constants.set(match[1], match[2]);
  return constants;
}

function scanFile(relativeFile, text) {
  const constants = collectStringConstants(text);
  const entries = [];

  const flagRegex = /\.\s*(getFlag|setFlag|unsetFlag)\s*\(\s*([^,\n)]+)\s*,\s*([^,\n)]+)(?:\s*,|\s*\))/g;
  let match;
  while ((match = flagRegex.exec(text))) {
    const operation = match[1];
    const namespace = resolveLiteralOrIdentifier(match[2], constants);
    const key = resolveLiteralOrIdentifier(match[3], constants);
    entries.push({
      kind: "foundry-flag",
      owner: "Foundry Document",
      operation,
      access: operation === "getFlag" ? "read" : operation === "setFlag" ? "write" : "delete",
      namespace: namespace.value,
      key: key.value,
      namespaceResolved: namespace.resolved,
      keyResolved: key.resolved,
      file: relativeFile,
      line: lineNumber(text, match.index),
      expression: match[0].replace(/\s+/g, " ").trim().slice(0, 200)
    });
  }

  const settingsRegex = /\bgame\s*\.\s*settings\s*\.\s*(register|get|set)\s*\(\s*([^,\n)]+)\s*,\s*([^,\n)]+)(?:\s*,|\s*\))/g;
  while ((match = settingsRegex.exec(text))) {
    const operation = match[1];
    const namespace = resolveLiteralOrIdentifier(match[2], constants);
    const key = resolveLiteralOrIdentifier(match[3], constants);
    entries.push({
      kind: "foundry-setting",
      owner: "game.settings",
      operation,
      access: operation === "get" ? "read" : "write",
      namespace: namespace.value,
      key: key.value,
      namespaceResolved: namespace.resolved,
      keyResolved: key.resolved,
      file: relativeFile,
      line: lineNumber(text, match.index),
      expression: match[0].replace(/\s+/g, " ").trim().slice(0, 200)
    });
  }

  const storageRegex = /\b(localStorage|sessionStorage)\s*\.\s*(getItem|setItem|removeItem)\s*\(\s*([^,\n)]+)(?:\s*,|\s*\))/g;
  while ((match = storageRegex.exec(text))) {
    const key = resolveLiteralOrIdentifier(match[3], constants);
    entries.push({
      kind: "web-storage",
      owner: match[1],
      operation: match[2],
      access: match[2] === "getItem" ? "read" : match[2] === "setItem" ? "write" : "delete",
      namespace: match[1],
      key: key.value,
      namespaceResolved: true,
      keyResolved: key.resolved,
      file: relativeFile,
      line: lineNumber(text, match.index),
      expression: match[0].replace(/\s+/g, " ").trim().slice(0, 200)
    });
  }

  const globalWriteRegex = /\b(game|globalThis)\s*\.\s*([A-Za-z_$][\w$]*)\s*=/g;
  while ((match = globalWriteRegex.exec(text))) {
    entries.push({
      kind: "public-global",
      owner: match[1],
      operation: "assign",
      access: "write",
      namespace: match[1],
      key: match[2],
      namespaceResolved: true,
      keyResolved: true,
      file: relativeFile,
      line: lineNumber(text, match.index),
      expression: match[0].replace(/\s+/g, " ").trim()
    });
  }

  const flagPathRegex = /flags\.([A-Za-z0-9_-]+)\.([A-Za-z0-9_.-]+)/g;
  while ((match = flagPathRegex.exec(text))) {
    entries.push({
      kind: "flag-path",
      owner: "Foundry flags path",
      operation: "path-reference",
      access: "unknown",
      namespace: match[1],
      key: match[2],
      namespaceResolved: true,
      keyResolved: true,
      file: relativeFile,
      line: lineNumber(text, match.index),
      expression: match[0]
    });
  }

  return entries;
}

function classifyLegacy(namespace, file) {
  if (namespace === "lancer-sitrep-tracker") return true;
  return normalizeSlashes(file).includes("legacy-sitrep-module");
}

function buildLedger(entries) {
  const grouped = new Map();
  for (const entry of entries) {
    const id = `${entry.kind}|${entry.namespace}|${entry.key}`;
    if (!grouped.has(id)) {
      grouped.set(id, {
        kind: entry.kind,
        owner: entry.owner,
        namespace: entry.namespace,
        key: entry.key,
        readers: [],
        writers: [],
        deleters: [],
        references: [],
        legacy: false,
        unresolved: false,
        migrationRequired: false
      });
    }
    const item = grouped.get(id);
    const site = { file: entry.file, line: entry.line, operation: entry.operation };
    if (entry.access === "read") item.readers.push(site);
    else if (entry.access === "write") item.writers.push(site);
    else if (entry.access === "delete") item.deleters.push(site);
    else item.references.push(site);
    item.legacy ||= classifyLegacy(entry.namespace, entry.file);
    item.unresolved ||= !entry.namespaceResolved || !entry.keyResolved;
  }

  for (const item of grouped.values()) {
    item.migrationRequired = item.legacy && (item.writers.length > 0 || item.deleters.length > 0 || item.kind === "public-global");
  }

  return [...grouped.values()].sort((a, b) => `${a.namespace}.${a.key}`.localeCompare(`${b.namespace}.${b.key}`));
}

function runAtlas(repositoryRoot, rootRelative) {
  const scanRoot = path.resolve(repositoryRoot, rootRelative);
  const files = collectFiles(scanRoot);
  const entries = [];
  for (const absolute of files) {
    const relative = normalizeSlashes(path.relative(repositoryRoot, absolute));
    entries.push(...scanFile(relative, fs.readFileSync(absolute, "utf8")));
  }
  const ledger = buildLedger(entries);
  return {
    schema_version: 1,
    tool: "state-namespace-atlas",
    version: SCRIPT_VERSION,
    root: normalizeSlashes(rootRelative),
    summary: {
      files: files.length,
      accessSites: entries.length,
      stateSurfaces: ledger.length,
      legacySurfaces: ledger.filter(item => item.legacy).length,
      migrationRequired: ledger.filter(item => item.migrationRequired).length,
      unresolved: ledger.filter(item => item.unresolved).length
    },
    ledger,
    accessSites: entries
  };
}

function printReport(report) {
  console.log("Frame Conn State / Namespace Atlas");
  console.log(`Root: ${report.root}`);
  console.log(`${report.summary.files} files | ${report.summary.stateSurfaces} state surfaces | ${report.summary.legacySurfaces} legacy | ${report.summary.migrationRequired} migration candidates`);
  if (report.ledger.length) {
    console.log("\nPersistence/public namespace ledger:");
    for (const item of report.ledger) {
      const marker = item.migrationRequired ? "MIGRATE" : item.legacy ? "LEGACY" : "CURRENT";
      console.log(`  ${marker.padEnd(8)} ${item.kind.padEnd(15)} ${item.namespace}.${item.key}`);
      console.log(`    readers ${item.readers.length} | writers ${item.writers.length} | deletes ${item.deleters.length} | refs ${item.references.length}`);
    }
  }
}

function selfTest() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "frame-conn-state-atlas-"));
  fs.mkdirSync(path.join(root, "scripts", "legacy-sitrep-module"), { recursive: true });
  fs.writeFileSync(
    path.join(root, "scripts", "legacy-sitrep-module", "state.js"),
    'const MODULE_ID = "lancer-sitrep-tracker"; const FLAG_KEY = "sitrep"; export function x(c){ c.getFlag(MODULE_ID, FLAG_KEY); c.setFlag(MODULE_ID, FLAG_KEY, {}); game.lancerSitrep = {}; }\n'
  );
  const report = runAtlas(root, ".");
  if (!report.ledger.some(item => item.namespace === "lancer-sitrep-tracker" && item.key === "sitrep" && item.migrationRequired)) {
    throw new Error("Self-test failed: legacy flag migration surface was not detected.");
  }
  if (!report.ledger.some(item => item.kind === "public-global" && item.key === "lancerSitrep")) {
    throw new Error("Self-test failed: public global API was not detected.");
  }
  fs.rmSync(root, { recursive: true, force: true });
  console.log("State / Namespace Atlas self-test PASSED");
}

const args = parseArgs(process.argv);
if (args.selfTest) {
  selfTest();
} else {
  const report = runAtlas(REPOSITORY_ROOT, args.root);
  const outputPath = path.resolve(REPOSITORY_ROOT, args.output);
  fs.writeFileSync(outputPath, `${JSON.stringify(report, null, 2)}\n`);
  printReport(report);
  console.log(`\nReport: ${normalizeSlashes(path.relative(REPOSITORY_ROOT, outputPath))}`);
}
